// fixupRangeValueForAscii rounds each field to the decimals of the ASCII log.
func fixupRangeValueForAscii(body MsgBody) MsgBody {
	m := *body.(*Range)
	m.Obs = make([]RangeObs, len(m.Obs))
	for i, o := range body.(*Range).Obs {
		o.PSR = roundDecimals(o.PSR, 3, 64)
		o.PSRStd = float32(roundDecimals(float64(o.PSRStd), 3, 32))
		o.ADR = roundDecimals(o.ADR, 6, 64)
		o.ADRStd = float32(roundDecimals(float64(o.ADRStd), 3, 32))
		o.Dopp = float32(roundDecimals(float64(o.Dopp), 3, 32))
		o.CN0 = float32(roundDecimals(float64(o.CN0), 1, 32))
		o.LockTime = float32(roundDecimals(float64(o.LockTime), 3, 32))
		m.Obs[i] = o
	}
	return &m
}

func roundDecimals(v float64, prec, bitSize int) float64 {
	r, err := strconv.ParseFloat(strconv.FormatFloat(v, 'f', prec, 64), bitSize)
	if err != nil {
		panic(err)
	}
	return r
}

