func TestChTrStatus(t *testing.T) {
	type fields struct {
		TrackingState  uint8
		PhaseLocked    bool
		ParityKnown    bool
		CodeLocked     bool
		SatSystem      SatSystem
		SignalType     uint8
		HalfCycleAdded bool
	}
	tests := []struct {
		status ChTrStatus
		expect fields
	}{
		{0x08009c24, fields{4, true, true, true, SatSystemGPS, 0, false}},
		{0x0a649f84, fields{4, true, true, true, SatSystemBeiDou, 19, false}},
		{0x11305c0b, fields{11, true, true, true, SatSystemGPS, 9, true}},
		{0x00011004, fields{4, false, false, true, SatSystemGLONASS, 0, false}},
	}
	for _, tc := range tests {
		t.Run(tc.status.String(), func(t *testing.T) {
			s := tc.status
			got := fields{s.TrackingState(), s.PhaseLocked(), s.ParityKnown(), s.CodeLocked(), s.SatSystem(), s.SignalType(), s.HalfCycleAdded()}
			if !reflect.DeepEqual(got, tc.expect) {
				t.Errorf("got  %+v\nwant %+v", got, tc.expect)
			}
		})
	}
}
